package com.networkmonitorpro.service; import android.app.*; import android.content.*; import android.os.*; import android.widget.RemoteViews; import androidx.core.app.NotificationCompat; import com.networkmonitorpro.R; public class NotificationHelper{ public static final String MONITOR="network_monitor", ALERTS="network_alerts", DOWNLOADS="downloads"; public static void createChannels(Context c){ if(Build.VERSION.SDK_INT>=26){NotificationManager nm=c.getSystemService(NotificationManager.class); nm.createNotificationChannel(new NotificationChannel(MONITOR,"Persistent monitoring",NotificationManager.IMPORTANCE_LOW)); nm.createNotificationChannel(new NotificationChannel(ALERTS,"Network alerts",NotificationManager.IMPORTANCE_DEFAULT)); nm.createNotificationChannel(new NotificationChannel(DOWNLOADS,"Download progress",NotificationManager.IMPORTANCE_LOW));}} public static Notification monitor(Context c,String text){RemoteViews rv=new RemoteViews(c.getPackageName(), R.layout.notification_monitor); rv.setTextViewText(R.id.notification_text,text); return new NotificationCompat.Builder(c,MONITOR).setSmallIcon(R.drawable.ic_network).setOngoing(true).setCustomContentView(rv).setContentTitle("Network Monitor Pro").setContentText(text).build();} public static void alert(Context c,String title,String msg){Notification n=new NotificationCompat.Builder(c,ALERTS).setSmallIcon(R.drawable.ic_network).setContentTitle(title).setContentText(msg).setAutoCancel(true).build(); ((NotificationManager)c.getSystemService(Context.NOTIFICATION_SERVICE)).notify((int)System.currentTimeMillis(),n);} public static Notification download(Context c,String name,int progress){return new NotificationCompat.Builder(c,DOWNLOADS).setSmallIcon(R.drawable.ic_network).setContentTitle(name).setContentText(progress+"% complete").setProgress(100,progress,false).setOngoing(progress<100).build();} }
